//! 📤️ Native snapshot export borrows authentic fields and retains only canonical codec state and final output pages.
use semio_framework_dsl_record::{BorrowedRecordSpec,native_encoding::FieldProjectionSource};
use semio_framework_job::{OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,StepContext,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind};
use semio_framework_value_persistent::list::PagedList;
use pack::record::BorrowedPackDocumentCursor;
use std::mem::size_of;
type Pages=PagedList<u8,{isize::MAX as usize}>;
type Bytes=semio_framework_value::paged::PagedBytes<{isize::MAX as usize}>;
const HEADER:usize=64;
/// 🫳️ The concrete snapshot owner declares original borrowed fields, metadata and its static envelope identity together.
pub struct OriginalSnapshotPackView<'a>{pub source:&'a dyn FieldProjectionSource,pub spec:BorrowedRecordSpec,pub envelope:&'static str}
/// 🧳️ One initiating caller owns bounded canonical encoding, partial final bytes and cancellation through full closure.
pub struct OriginalSnapshotPackExport{binding:Option<OriginalSourceBinding>,decoder:(u64,u64),epoch:u64,identity:usize,envelope:&'static str,cursor:BorrowedPackDocumentCursor,pages:Pages,scratch:[u8;64],pending:usize,offset:usize,prefix:usize,complete:bool,closing:bool}
fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,text)}
fn page(error:semio_framework_value_persistent::list::PagedListError)->ValueError{invalid(error.reason)}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes,..Default::default()}}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn work(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>)->Result<bool,OriginalTurnFailure>{let mut output=None;let grant=cx.retained_grant();admit_original_construction(cx,&mut output,construction(d),|_|run(grant).map(|p|((),p)))?;Ok(output.is_some())}
impl OriginalSnapshotPackExport{
 pub fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed(size_of::<Self>()+size_of::<Option<Box<Self>>>())}}
 pub fn boxed_release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),..fixed(size_of::<Option<Box<Self>>>())}}
 /// 🎟️ Captures the actual source address and external frontier without constructing a replacement snapshot.
 pub fn admit(view:OriginalSnapshotPackView<'_>,epoch:u64,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if output.is_some(){return Err(invalid("snapshot Pack export destination is occupied").into())}semio_framework_os_semio::declared_envelope_prefix_len(view.envelope,semio_framework_os_semio::Component::Pack,1)?;let decoder=cx.native_receiving_identity().ok_or_else(||invalid("snapshot Pack export requires its original decoder"))?;let binding=OriginalSourceBinding::borrow(cx);let d=Self::capture_demands();admit_original_construction(cx,output,construction(d),|_|Ok((Box::new(Self{binding:Some(binding),decoder,epoch,identity:view.source.projection_identity(),envelope:view.envelope,cursor:Default::default(),pages:Pages::empty(),scratch:[0;64],pending:0,offset:0,prefix:0,complete:false,closing:false}),progress(d))))}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if self.binding.is_none_or(|binding|!binding.matches(cx))||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid("snapshot Pack export changed its original caller or decoder"))}Ok(())}
 pub fn ready(&self)->bool{self.binding.is_some()&&self.complete&&self.cursor.terminal_is_empty()&&self.offset==self.pending&&!self.closing}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.cursor.terminal_is_empty()&&self.pages.terminal_is_empty()}
 /// 📏️ Quotes the next real allocation, bounded codec work, final byte donation or native close event.
 pub fn advance_demands(&self)->Result<RetirementDemand,ValueError>{if self.offset<self.pending{if !self.pages.has_reserved_slot(){return Ok(RetirementDemand{copy_bytes:self.pages.next_reserve_copy_byte_demand().map_err(page)?+HEADER,capacity_bytes:self.pages.next_allocation_bytes().map_err(page)?,depth:self.pages.next_reserve_depth_demand().map_err(page)?.max(1),release_bytes:0})}return Ok(fixed(HEADER+(self.pending-self.offset).min(64).min(self.pages.capacity()-self.pages.len())))}let prefix=semio_framework_os_semio::declared_envelope_prefix_len(self.envelope,semio_framework_os_semio::Component::Pack,1)?;if self.prefix<prefix{return Ok(fixed(HEADER+(prefix-self.prefix).min(64)))}if self.complete{if self.cursor.terminal_is_empty(){return Ok(fixed(HEADER))}let d=self.cursor.retirement_demands()?;return Ok(RetirementDemand{copy_bytes:d.copy_bytes+HEADER,..d})}Ok(RetirementDemand{copy_bytes:self.cursor.next_copy_byte_demand()?+HEADER,capacity_bytes:self.cursor.next_capacity_byte_demand()?,depth:self.cursor.next_depth_demand()?,release_bytes:0})}
 /// ✍️ Reborrows only the unchanged original snapshot and emits canonical Pack bytes into paid final pages.
 pub fn advance(&mut self,view:OriginalSnapshotPackView<'_>,epoch:u64,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if epoch!=self.epoch||view.source.projection_identity()!=self.identity||view.envelope!=self.envelope{return Err(invalid("snapshot Pack export changed its original frontier or fields").into())}if self.closing{return Err(invalid("closing snapshot Pack export cannot resume").into())}if self.ready(){return Ok(true)}if cx.is_cancelled(){return Ok(false)}let d=self.advance_demands()?;work(cx,d,|grant|{if self.offset<self.pending{if !self.pages.has_reserved_slot(){let mut p=self.pages.reserve_one_funded(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-HEADER,..grant}).map_err(|e|page(e.refusal()).with_retained_progress(RetainedCloneProgress{retained_capacity_bytes:e.allocated_bytes,..Default::default()}))?;p.copied_bytes+=HEADER;return Ok(p)}let count=(self.pending-self.offset).min(64).min(self.pages.capacity()-self.pages.len()).min(grant.maximum_copy_bytes-HEADER);for index in self.offset..self.offset+count{self.pages.push_reserved(self.scratch[index]).map_err(|_|invalid("snapshot Pack final page lost its reservation"))?;}self.offset+=count;return Ok(progress(fixed(count+HEADER)))}let prefix=semio_framework_os_semio::declared_envelope_prefix_len(self.envelope,semio_framework_os_semio::Component::Pack,1)?;if self.prefix<prefix{let count=(prefix-self.prefix).min(64);for index in 0..count{self.scratch[index]=semio_framework_os_semio::declared_binary_prefix_byte(self.envelope,semio_framework_os_semio::Component::Pack,1,self.prefix+index)?.ok_or_else(||invalid("snapshot Pack envelope prefix disappeared"))?;}self.prefix+=count;self.pending=count;self.offset=0;return Ok(progress(d))}let child=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-HEADER,..grant};let step=if self.complete{self.cursor.close(child)}else{self.cursor.advance(view.source,view.spec,&mut self.scratch,child)};match step{Ok(step)=>{if !self.complete{self.pending=step.written_bytes;self.offset=0;self.complete=step.complete;}let mut p=step.progress;p.copied_items=1;p.copied_bytes+=HEADER;Ok(p)},Err(failure)=>{self.closing=true;let p=failure.reason.retained_progress();Err(failure.reason.with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:p.copied_bytes+HEADER,..p}))}}})?;Ok(self.ready())}
 pub fn take_demands()->RetirementDemand{fixed(size_of::<Option<Bytes>>()+HEADER)}
 /// 🫴️ Transfers the unique final byte owner only after every codec locator and compressor closes.
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<Bytes>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.ready()||output.is_some(){return Err(invalid("snapshot Pack export is not ready for its unique destination").into())}let d=Self::take_demands();work(cx,d,|_|{*output=Some(Bytes::from_retained_bytes(std::mem::replace(&mut self.pages,Pages::empty())));self.binding=None;Ok(progress(d))})}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(fixed(1))}if !self.cursor.terminal_is_empty(){let d=self.cursor.retirement_demands()?;return Ok(RetirementDemand{copy_bytes:d.copy_bytes+HEADER,..d})}if !self.pages.is_empty(){return Ok(RetirementDemand{depth:self.pages.next_pop_depth_demand().map_err(page)?.max(1),..fixed(HEADER+self.pages.len().min(64))})}if !self.pages.terminal_is_empty(){return Ok(RetirementDemand{release_bytes:self.pages.next_release_allocation_bytes().map_err(page)?,depth:self.pages.next_release_depth_demand().map_err(page)?.max(1),..fixed(HEADER)})}Ok(fixed(HEADER))}
 /// ♻️ Closes the actual compressor, field locators and partial final pages through the initiating caller.
 pub fn close(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}self.validate(cx)?;let d=self.close_demands()?;close_original_retained_step(cx,d,|grant|{if !self.closing{self.closing=true;return Ok(RetainedCloneStep::Progress(progress(d)))}if !self.cursor.terminal_is_empty(){let step=self.cursor.close(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-HEADER,..grant}).map_err(|failure|failure.reason)?;let mut p=step.progress;p.copied_items=1;p.copied_bytes+=HEADER;return Ok(RetainedCloneStep::Progress(p))}if !self.pages.is_empty(){let count=self.pages.len().min(64).min(grant.maximum_copy_bytes-HEADER);for _ in 0..count{self.pages.pop();}return Ok(RetainedCloneStep::Progress(progress(fixed(count+HEADER))))}if !self.pages.terminal_is_empty(){let step=self.pages.release_empty_page(grant.maximum_release_bytes).map_err(page)?;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{released_bytes:step.released_allocation_bytes,..progress(fixed(HEADER))}))}self.binding=None;Ok(RetainedCloneStep::Complete(progress(d)))})?;Ok(self.terminal_is_empty())}
}
impl Drop for OriginalSnapshotPackExport{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original snapshot Pack export requires complete physical closure")}}
